static BUTTONS_LIST: [u16; 3] = [0x110, 0x111, 0x112];

// static void set_bit(uint8_t *tab, int k)
#[inline]
unsafe fn set_bit(tab: *mut u8, k: c_int) {
    let idx = (k >> 3) as usize;
    let bit: u8 = 1u8 << ((k & 7) as u32);
    *tab.add(idx) |= bit;
}

