// ---------------------------------------------------------------- little endian

#[inline]
unsafe fn put_le16(ptr: *mut u8, v: u16) {
    *ptr = v as u8;
    *ptr.add(1) = (v >> 8) as u8;
}

#[inline]
unsafe fn put_le32(ptr: *mut u8, v: u32) {
    *ptr = v as u8;
    *ptr.add(1) = (v >> 8) as u8;
    *ptr.add(2) = (v >> 16) as u8;
    *ptr.add(3) = (v >> 24) as u8;
}

#[inline]
unsafe fn put_le64(ptr: *mut u8, v: u64) {
    put_le32(ptr, v as u32);
    put_le32(ptr.add(4), (v >> 32) as u32);
}

#[inline]
